  const sj = yi.get(a.y);
  const gi = xi.get(b.x);
  const gj = yi.get(b.y);
  if (blockedNode[node(si, sj)] || blockedNode[node(gi, gj)]) return null;

  const S = NX * NY * 5;
  const g = new Float64Array(S).fill(Infinity);
  const parent = new Int32Array(S).fill(-1);
  const closed = new Uint8Array(S);
