  const start = node(si, sj) * 5 + NO_DIR;
  g[start] = 0;
  heap.push(Math.abs(xs[si] - xs[gi]) + Math.abs(ys[sj] - ys[gj]), start);

  let goalState = -1;
  while (heap.size > 0) {
    const { value: s } = heap.pop();
    if (closed[s]) continue;
    closed[s] = 1;
    const dir = s % 5;
    const n = (s - dir) / 5;
    const i = Math.floor(n / NY);
    const j = n % NY;
    if (i === gi && j === gj) {
      goalState = s;
      break;
    }
    for (let d = 0; d < 4; d++) {
