  if (goalState < 0) return null;

  const cells = [];
  for (let s = goalState; s !== -1; s = parent[s]) {
    const n = Math.floor(s / 5);
    cells.push({ x: xs[Math.floor(n / NY)], y: ys[n % NY] });
