    for (const e of json.elements ?? []) {
      const fields = {};
      for (const [k, v] of Object.entries(e)) {
        if (k === 'id') continue;
        if (k === 'style') for (const [sk, sv] of Object.entries(v ?? {})) fields[`style.${sk}`] = sv;
        else fields[k] = v;
      }
      doc._applyPrim({ op: 'create', id: e.id, kind: 'element', ts: zeroTs(), fields });
    }
  }
  doc._clock = maxClock;
  return doc;
}

