      persistDoc(rt);
      return sendJSON(res, 201, reply);
    }
    if (rest[0] === 'comments' && rest.length === 3 && rest[2] === 'resolve' && m === 'POST') {
      requireRole(rt, user, 'viewer');
      const c = rt.meta.comments.find((x) => x.id === rest[1]);
      if (!c) fail(404, 'not_found', 'comment not found');
