$('#distH').onclick = () => mutate(() => state.doc.distribute([...state.selection], 'horizontal'));
$('#distV').onclick = () => mutate(() => state.doc.distribute([...state.selection], 'vertical'));
$('#layoutGo').onclick = () => {
