  const next = list[idx + 1];
  const after = list[idx + 2];
  if (!next) z = keyBetween(e.z, null);
  else z = after && after.z > next.z ? keyBetween(next.z, after.z) : keyBetween(next.z, null);
  break;
}
case 'backward': {
