  assert.equal(a.get('p').x, 50);
});

test('setStyle, group/ungroup, layers', () => {
  const d = createDocument({ id: 'd', actor: 'a' });
  d.apply(rect('a', 0, 0));
  d.apply(rect('b', 0, 0));
